<script setup lang="ts">import {onMounted,ref} from 'vue';import ManagementLayout from '@/components/ManagementLayout.vue';import {platformApi,type Device,type Classroom} from '@/api/platform';const devices=ref<Device[]>([]);const classrooms=ref<Classroom[]>([]);const loading=ref(true);const error=ref('');async function load(){loading.value=true;try{const [d,c]=await Promise.all([platformApi.devices(),platformApi.classrooms()]);devices.value=d.data;classrooms.value=c.data}catch{error.value='设备信息加载失败，请重试。'}finally{loading.value=false}}onMounted(load);function status(v:string){return v==='online'?'在线':v==='fault'?'故障':v==='disabled'?'停用':'离线'}</script>
<template><ManagementLayout><h1>教室与设备</h1><p class="muted">查看设备在线状态与绑定信息</p><div class="toolbar"><button class="button" @click="load">刷新</button></div><div class="panel"><p v-if="loading">加载中…</p><p v-else-if="error" class="bad">{{error}}</p><table v-else class="table"><thead><tr><th>设备</th><th>设备编码</th><th>类型</th><th>状态</th><th>最近在线</th></tr></thead><tbody><tr v-for="item in devices" :key="item.id"><td>{{item.name}}</td><td>{{item.deviceCode}}</td><td>{{item.type}}</td><td><span class="badge" :class="item.status==='online'?'ok':item.status==='fault'?'bad':'warn'">{{status(item.status)}}</span></td><td>{{item.lastOnlineAt||'暂无记录'}}</td></tr></tbody></table><p v-if="!loading&&!devices.length">暂无设备；当前可见教室 {{classrooms.length}} 间。</p></div></ManagementLayout></template>
